"""Mater Misericordiae Secondary School, Rumomasi — SS3 weekly lesson notes
(Second Term, 2026/2027) · Weeks 7-12 · Biology & Chemistry."""

SS3_BIO2 = [
 ("Classification of Organisms",
  [("Introduction", ["Classification is the grouping of organisms by shared features. It makes the study of life orderly and reveals evolutionary relationships. The modern hierarchy runs: kingdom → phylum/division → class → order → family → genus → species."]),
   ("The five kingdoms", ["<b>Monera</b> — bacteria and blue-green algae: prokaryotic (no true nucleus).", "<b>Protista</b> — protozoa (amoeba, paramecium) and algae: eukaryotic, single-celled or simple. <b>Fungi</b> — moulds, yeast, mushrooms: no chlorophyll, cell wall of chitin, saprophytic. <b>Plantae</b> — green plants: photosynthetic, cellulose walls. <b>Animalia</b> — heterotrophic, motile, no cell walls.", "Beyond the five: viruses are acellular — nucleic acid inside a protein coat; they are considered non-cellular particles, not placed in the kingdoms."]),
   ("Binomial nomenclature", ["Linnaeus: every organism has a genus and a species name in Latin — <i>Homo sapiens</i> (man), <i>Zea mays</i> (maize). The name is italicised (or underlined), the genus capitalised, the species in lower case."]),
   ("Kingdoms in the exam", ["Common examples: Monera — <i>Vibrio cholerae</i>; Protista — <i>Amoeba</i>, <i>Plasmodium</i>; Fungi — <i>Penicillium</i>, <i>Mucor</i>; Plantae — <i>Hibiscus</i>, <i>Pinus</i>; Animalia — <i>Chicken</i>, <i>Man</i>."]),
   ("Class evaluation", ["List the five kingdoms with one feature of each.", "What does binomial nomenclature mean?", "In which kingdom do you place bacteria and why?", "Why are viruses excluded from the five kingdoms?"])]),
 ("Micro-organisms Around Us & Disease",
  [("Introduction", ["Micro-organisms (microbes) are organisms too small to be seen with the naked eye: bacteria, protozoa, fungi, algae and viruses. They are found everywhere — in soil, water, air and in living bodies — and they may be useful or harmful."]),
   ("Useful and harmful roles", ["Useful: decomposition and nutrient cycling; nitrogen fixation; fermentation (bread, beer, yoghurt, garri); the production of antibiotics (penicillin from <i>Penicillium</i>); sewage treatment; vitamins in the gut. Harmful: they cause disease (pathogens), spoil food and toxify it (the aflatoxin of groundnuts), and cause decay."]),
   ("Pathogenic micro-organisms", ["<b>Bacteria</b> — cholera (<i>Vibrio cholerae</i>), typhoid (<i>Salmonella typhi</i>), tuberculosis (<i>Mycobacterium</i>), whooping cough.", "<b>Protozoa</b> — malaria (<i>Plasmodium</i>), amoebic dysentery (<i>Entamoeba histolytica</i>). <b>Viruses</b> — smallpox, polio, measles, HIV, COVID-19. <b>Fungi</b> — ringworm, athlete's foot, thrush. <b>Worms</b> (helminths) — roundworm, hookworm, tapeworm."]),
   ("Transmission", ["Air (droplets — coughs, sneezes), water (cholera, typhoid), food (contaminated — food poisoning), vectors (the female Anopheles mosquito for malaria; the testse fly for trypanosomiasis; houseflies carry pathogens), contact (skin, sexual contact — HIV, gonorrhoea), and contaminated instruments (needles, blades)."]),
   ("Class evaluation", ["State two useful and two harmful activities of micro-organisms.", "Name the causative organisms of malaria and cholera.", "How is typhoid spread?", "Differentiate a pathogen from a vector with examples."])]),
 ("Micro-organisms & Public Health (Prevention)",
  [("Introduction", ["Public health is the science of protecting and improving the health of communities — through sanitation, immunisation, safe water, health education and disease control. Micro-organisms are central to public health because they cause epidemics."]),
   ("Methods of control", ["<b>Immunisation</b> — vaccines train the immune system (BCG, polio, measles, tetanus, yellow fever); <b>sanitation</b> — pit latrines, refuse collection, sewage treatment; <b>safe water</b> — boiling, chlorination, boreholes; <b>food hygiene</b> — washing, thorough cooking, covering; <b>vector control</b> — mosquito nets and indoor spraying (malaria), insecticide-treated bednets, draining stagnant water, fly proofing; <b>chemotherapy</b> — antibiotics for bacteria, antimalarials; and <b>health education</b> — hand washing, the danger of open defecation, and prompt treatment."]),
   ("Diseases in Nigeria and their control", ["Malaria (the highest killer), typhoid, cholera, tuberculosis, HIV/AIDS, measles and polio. The National Primary Health Care Development Agency runs immunisation and health programmes; the WHO and UNICEF support the campaigns."]),
   ("The laboratory view", ["Cultures on agar plates show colonies; the Gram stain distinguishes bacteria; microscopy and biochemical tests identify species; the spread-plate and pour-plate methods isolate pure cultures."]),
   ("Class evaluation", ["Define public health.", "State four ways of preventing the spread of cholera.", "Name two diseases controlled by immunisation.", "Why is mosquito control central to the fight against malaria?"])]),
 ("HIV/AIDS & Public Health",
  [("Introduction", ["HIV (Human Immunodeficiency Virus) infects the helper T-cells of the immune system; AIDS is the terminal stage when the immune system collapses and opportunistic infections set in. It is a global public health issue and a manageable chronic disease with antiretroviral therapy (ART)."]),
   ("The biology of HIV", ["HIV is a retrovirus: its genetic material is RNA, and the enzyme reverse transcriptase copies it into DNA which inserts into the host cell's genome. The virus is transmitted by body fluids — blood, semen, vaginal fluid and breast milk — not by casual contact, mosquitoes, or sharing food."]),
   ("Progression and opportunistic infections", ["The acute phase (flu-like symptoms), the asymptomatic phase (5–10 years, the CD4 count falls), and AIDS (CD4 below 200 cells/mm³, with opportunistic diseases — tuberculosis, pneumonia, candidiasis, Kaposi's sarcoma, wasting). Diagnosis: antibody tests (the rapid test, ELISA), with confirmatory Western blot or PCR."]),
   ("Public health response in Nigeria", ["The National Agency for the Control of AIDS (NACA) coordinates the response; prevention: ABC (Abstinence, Be faithful, Condoms), PMTCT (prevention of mother-to-child transmission), safe blood transfusion, harm reduction and testing; treatment: free ART, which suppresses the virus and prevents transmission (U=U — undetectable = untransmittable); and the reduction of stigma and discrimination."]),
   ("Class evaluation", ["Explain why HIV is called a retrovirus.", "State three routes of transmission and three non-routes.", "What are opportunistic infections and why do they appear in AIDS?", "What does U=U mean?"])]),
 ("Economic Importance of Organisms",
  [("Introduction", ["Organisms — plants, animals and micro-organisms — are of immense economic importance to the Nigerian economy: food, medicine, industry and the environment. This week surveys that importance and how it is managed."]),
   ("Micro-organisms in industry", ["Fermentation: garri, ogi, bread, beer, wine, yoghurt, cheese, soy sauce; antibiotics (penicillin, streptomycin); enzymes in detergents and food processing; insulin and vaccines by genetic engineering; biogas (methane) from waste; and sewage treatment."]),
   ("Plants and animals of economic note", ["Food crops (cassava, maize, rice, yam), cash crops (cocoa, oil palm, rubber, cashew, cotton), timber (mahogany, iroko), medicinal plants (neem, moringa, ginger); livestock (cattle, poultry, goats), fisheries and beekeeping; and the wild species that support tourism and the ecosystem (pollination, seed dispersal)."]),
   ("Harmful species and control", ["Pests (stem borers, weevils, rodents), parasites (worms, ticks), pathogens, weeds and invasive species (water hyacinth blocking the Niger) — controlled by integrated pest management (IPM): resistant varieties, biological control, cultural practices and careful chemical use."]),
   ("Biodiversity and conservation", ["Ecosystem services (clean water, fertile soil, pollination) are worth more than the direct harvests; conservation — protected areas (national parks: Cross River, Yankari), the Endangered Species laws, sustainable fishing and forestry — preserves this capital for the future."]),
   ("Class evaluation", ["State three industrial uses of micro-organisms.", "Name four cash crops of Nigeria.", "What is integrated pest management?", "Why is biodiversity economically important?"])]),
 ("Micro-organisms in Biotechnology & Industry",
  [("Introduction", ["Biotechnology is the use of living organisms or their products to make useful goods and services. Man has used micro-organisms for thousands of years — first unknowingly (bread, beer) and today by design (insulin, vaccines, GM crops)."]),
   ("Traditional biotechnology", ["Fermentation — the conversion of sugar by micro-organisms: <b>yeast</b> makes bread (CO₂ leavens the dough), beer, wine, ogi and palm wine; <b>bacteria</b> (Lactobacillus) make yoghurt, cheese, soy sauce and the Nigerian 'ugba'; <b>moulds</b> ripen cheese and make soy sauce."]),
   ("Modern biotechnology", ["<b>Genetic engineering</b> — genes are transferred between organisms: human insulin and growth hormone are produced by bacteria; the hepatitis B vaccine in yeast; <b>transgenic crops</b> — pest-resistant maize (Bt), vitamin-A-enriched 'golden rice'. <b>Tissue culture</b> — plants (yam, cassava, banana) are multiplied from tiny pieces in sterile media, disease-free and fast. <b>Bioremediation</b> — micro-organisms are used to clean oil spills and sewage."]),
   ("Applications and safety", ["Medicine: antibiotics (penicillin from the mould Penicillium), vaccines, diagnostic kits; agriculture: biofertilisers (nitrogen-fixing Rhizobium), silage, the ripening of cheese; industry: citric acid, enzymes in detergents. Safety: the regulation of GMOs in Nigeria (the National Biosafety Management Agency), the ethics of gene editing, and the debate on genetically modified foods."]),
   ("Class evaluation", ["Define biotechnology.", "Name two micro-organisms and one product of each.", "How is human insulin produced today?", "What is tissue culture?", "State two benefits and one risk of genetically modified crops."])]),
]

SS3_CHEM2 = [
 ("Quantitative Chemistry & Stoichiometry",
  [("Introduction", ["Quantitative chemistry deals with the amounts of substances in reactions: the mole, molar mass, molar volume, concentrations, and the calculations derived from balanced equations. It is 'the arithmetic of chemistry'."]),
   ("Core relationships", ["n = mass ÷ molar mass; n = volume (dm³) ÷ 24 (at r.t.p.); concentration = n ÷ volume (dm³); number of particles = n × 6.02 × 10²³. Stoichiometry: use the balanced equation's mole ratio. Percentage composition of a compound = mass of the element ÷ molar mass × 100. Empirical formula from the masses; molecular formula = n × empirical formula."]),
   ("Worked example", ["What mass of CaO is obtained from 50 g of CaCO3 (CaCO3 → CaO + CO2)? Molar masses: CaCO3 = 100, CaO = 56. Moles CaCO3 = 50/100 = 0.5; ratio 1:1 → 0.5 mol CaO; mass = 0.5 × 56 = 28 g."]),
   ("Titration calculations", ["In a titration, moles acid = moles alkali × (ratio). Example: 25.0 cm³ of 0.100 mol/dm³ NaOH neutralises 20.0 cm³ of HCl; moles NaOH = 0.100 × 0.025 = 0.0025; moles HCl = 0.0025; concentration = 0.0025 ÷ 0.020 = 0.125 mol/dm³."]),
   ("Class evaluation", ["Calculate the number of moles in 22 g of CO2 (C = 12, O = 16).", "What mass of iron is in 40 g of Fe2O3 (Fe = 56, O = 16)?", "Define the empirical formula.", "25.0 cm³ of 0.08 mol/dm³ H2SO4 neutralises 20.0 cm³ of NaOH. Find the concentration of the NaOH (H2SO4 + 2NaOH → Na2SO4 + 2H2O)."])]),
 ("Practical Chemistry Skills (Volumetric & Descriptive)",
  [("Introduction", ["Practical chemistry is examined both practically (the WASSCE practical paper) and descriptively. The skills: accurate weighing and measuring, titration, gas collection, the correct use of apparatus, safe heating, and clear recording of observations and inferences."]),
   ("Apparatus and their use", ["Burette (titrant delivery), pipette (fixed volumes, with a filler), conical flask (titrated solution), measuring cylinder (rough volumes), beaker, test tube and boiling tube, evaporating dish (crystallisation), crucible (strong heating), funnel, filter paper, watch glass, spatula, retort stand, Bunsen burner, water bath, gas jar. Read the meniscus at eye level; wash and rinse apparatus; repeat titrations to concordant values (within 0.1 cm³)."]),
   ("Gas tests", ["O2 — rekindles a glowing splint; H2 — a lighted splint gives a pop; CO2 — turns limewater milky; NH3 — turns damp red litmus blue and forms white fumes with HCl; SO2 — turns acidified potassium dichromate green; Cl2 — bleaches damp litmus; H2S — blackens lead acetate paper."]),
   ("Tests for ions", ["Cations: flame tests (Na+ — yellow; K+ — lilac; Ca2+ — brick red; Cu2+ — blue-green), NaOH (Cu2+ — blue precipitate; Fe2+ — green then brown; Fe3+ — reddish-brown; Al3+/Zn2+ — white, soluble in excess NaOH; NH4+ — ammonia on warming). Anions: Cl− — white AgCl precipitate (soluble in ammonia (dilute)); SO42− — white BaSO4 (insoluble in HCl); CO32− — effervescence with acid (CO2); NO3− — brown ring."]),
   ("Class evaluation", ["How do you test for hydrogen gas?", "What is the flame colour of sodium? Of potassium?", "Describe the test for a chloride ion.", "Why must a pipette be rinsed with the solution it will measure?"])]),
 ("Separation & Purification (Advanced)",
  [("Introduction", ["Separation and purification methods exploit differences in the physical properties of the components of a mixture: particle size, solubility, boiling point, density and the adsorption of substances to a stationary phase."]),
   ("Techniques and their theory", ["<b>Filtration</b> — insolubility; <b>evaporation and crystallisation</b> — solubility differences (recrystallisation purifies a solid); <b>simple distillation</b> — different boiling points (water from salt); <b>fractional distillation</b> — close boiling points (air → N2, O2; crude oil → fractions; ethanol–water); <b>separating funnel</b> — immiscible liquids of different densities (oil and water); <b>chromatography (paper, thin-layer, column, gas)</b> — different affinities for the mobile and stationary phases (identify dyes, inks, food colouring; calculate Rf = distance moved by the component ÷ distance moved by the solvent); <b>centrifugation</b> — density (blood cells); <b>sublimation</b> — iodine, ammonium chloride; <b>magnetic separation and decantation</b>."]),
   ("Purifying a product", ["Choose the method by the properties; test the purity by melting/boiling point (a pure substance has a sharp, constant value) or by chromatography (a pure substance gives one spot)."]),
   ("Class evaluation", ["How would you separate a mixture of sand, salt and iodine?", "What is Rf in chromatography?", "Why does fractional distillation separate crude oil?", "How is the purity of a solid checked?"])]),
 ("Radiochemistry Basics",
  [("Introduction", ["Radiochemistry is the chemistry of radioactive substances — elements whose nuclei are unstable and decay spontaneously, emitting radiation. The three types of radiation are alpha (α), beta (β) and gamma (γ)."]),
   ("Radiation and decay", ["<b>Alpha</b> — a helium nucleus (2 protons + 2 neutrons): heavy, positive, weakly penetrating (stopped by paper). <b>Beta</b> — an electron from the nucleus: light, fast, penetrates a few mm of aluminium. <b>Gamma</b> — high-energy electromagnetic radiation: very penetrating (needs lead or concrete). Half-life (t½) is the time for half the nuclei to decay: after one t½ half remains, after two t½ a quarter, after three an eighth."]),
   ("Nuclear equations", ["The mass and atomic numbers balance: ²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He (alpha); ¹⁴₆C → ¹⁴₇N + ⁰₋₁e (beta). Isotopes decay at their own rates — C-14 dating uses the 5,730-year half-life."]),
   ("Uses and safety", ["Medicine: radiotherapy for cancer (Co-60, I-131 for the thyroid), diagnosis (tracers, imaging); industry: thickness gauges, sterilisation of equipment and food; agriculture: mutation breeding, pest control (sterile insect technique); archaeology: radiocarbon dating. Safety: time, distance and shielding; the ALARA principle; lead aprons, film badges and the careful disposal of sources."]),
   ("Class evaluation", ["Name the three types of radiation and their penetrating powers.", "Define the half-life.", "Write the alpha decay equation of ²²⁶₈₈Ra.", "State two uses of radioactivity in medicine."])]),
 ("Energy Changes (Thermochemistry) & Rates of Reaction",
  [("Introduction", ["Chemical reactions involve energy and time. Thermochemistry studies the heat changes; kinetics studies the speed. Both are core WAEC/NECO topics — and both explain many everyday processes."]),
   ("Exothermic and endothermic reactions", ["<b>Exothermic</b> — heat is released (the products have less energy than the reactants; ΔH is negative): combustion, respiration, the reaction of sodium or calcium with water, neutralisation, the slaking of lime. <b>Endothermic</b> — heat is absorbed (ΔH is positive): photosynthesis, the decomposition of calcium carbonate and ammonium chloride, the dissolving of ammonium nitrate. Energy profiles show the activation energy — the minimum energy colliding particles need to react; a catalyst lowers it."]),
   ("Measuring heat changes", ["In the school laboratory: the simple calorimeter — a known mass of water (or solution) in a cup, the temperature measured before and after the reaction, and the heat calculated: q = mcΔT (m = mass of water in g; c = 4.2 J g⁻¹ K⁻¹; ΔT = the temperature change); then ΔH = −q ÷ moles of the limiting reactant (in kJ/mol)."]),
   ("Rates of reaction", ["Rate = change in concentration/amount ÷ time — measured by the volume of gas collected, the loss of mass, or the time for a mark to disappear (the 'disappearing cross' with sodium thiosulphate and acid). Factors that increase the rate: <b>concentration</b> (more particles per volume — more frequent collisions), <b>temperature</b> (faster, more energetic collisions — about a doubling per 10 °C), <b>surface area</b> (crushing a solid), <b>pressure</b> (gases), and a <b>catalyst</b> (lowers the activation energy)."]),
   ("Class evaluation", ["Distinguish exothermic from endothermic reactions with two examples each.", "What is activation energy?", "Calculate the heat absorbed when 100 g of water warms from 25 to 40 °C.", "State the four factors that affect the rate of a reaction.", "Why does a powder react faster than a lump?"])]),
 ("Acids, Bases & Salts (Revision & Applications)",
  [("Introduction", ["Acids, bases and salts are the oldest families of chemistry — and the most examined. This week revises their definitions, properties, reactions and everyday uses at the WAEC/NECO level."]),
   ("Acids", ["Arrhenius: acids donate H⁺ in water; the Brønsted–Lowry definition: acids are proton donors. Properties: sour taste, turn blue litmus red, conduct electricity, react with metals (release H₂), with carbonates (release CO₂), with bases (neutralisation). Strong acids ionise fully (HCl, H₂SO₄, HNO₃); weak acids partly (ethanoic, citric, carbonic). Uses: H₂SO₄ in car batteries and fertilisers, HCl in the stomach, HNO₃ in explosives and fertilisers."]),
   ("Bases and alkalis", ["A base is a metal oxide or hydroxide that neutralises acids; an alkali is a base soluble in water (NaOH, KOH, Ca(OH)₂, NH₃ solution). Properties: soapy feel, turn red litmus blue, corrosive. Uses: slaked lime in building and agriculture (to neutralise acidic soil and for the treatment of sewage), caustic soda in soap making, ammonia in fertilisers and cleaning agents."]),
   ("Salts and their preparation", ["A salt is formed when the H⁺ of an acid is replaced by a metal or ammonium ion. Types: normal, acidic, basic, double and complex salts. Preparation: the acid + metal, + metal oxide, + carbonate (all by evaporation/crystallisation); acid + alkali (titration — to get a soluble salt with a known concentration); and double decomposition (for insoluble salts — e.g. AgCl, BaSO₄, by mixing solutions and filtering). Solubility rules: all nitrates are soluble; chlorides are soluble except AgCl, PbCl₂ and Hg₂Cl₂; sulphates soluble except BaSO₄, PbSO₄, CaSO₄; carbonates are insoluble except those of sodium, potassium and ammonium."]),
   ("Class evaluation", ["Define an acid and a base by the Brønsted–Lowry theory.", "State three properties of acids.", "Name the products of the reaction of an acid with a carbonate.", "Which method prepares silver chloride?", "Give one use each of H₂SO₄, NaOH and slaked lime."])]),
]
